 [STAThread] public static void Main(string[] args){var testState=Environment.GetEnvironmentVariable("DESKTOPBOX_TEST_STATE");if(!string.IsNullOrEmpty(testState))Store.PathName=testState;if(args.Contains("--restore-icons")){try{DesktopIcons.Recover();DesktopLayer.RestoreNative();MessageBox.Show("已恢复有记录的原桌面图标。");}catch(Exception ex){MessageBox.Show("恢复失败，记录已保留："+ex.Message);}return;}if(args.Contains("--crash-test")){Environment.Exit(CrashTest.Run());return;} if(args.Length==2&&args[0]=="--watch"){try{try{System.Diagnostics.Process.GetProcessById(int.Parse(args[1])).WaitForExit();}catch(ArgumentException){}DesktopIcons.Recover();DesktopLayer.RestoreNative();}catch(Exception ex){File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"recovery-error.txt"),ex.ToString());}return;} if(args.Contains("--self-test")){Environment.Exit(SelfTest.Run());return;} var app=new Program();app.DispatcherUnhandledException+=(_,e)=>LogCrash("WPF dispatcher",e.Exception);AppDomain.CurrentDomain.UnhandledException+=(_,e)=>LogCrash("AppDomain",e.ExceptionObject);Environment.ExitCode=app.Run();}
 static void LogCrash(string source,object? error){try{var directory=Path.GetDirectoryName(Store.PathName)!;Directory.CreateDirectory(directory);File.AppendAllText(Path.Combine(directory,"crash.log"),$"[{DateTimeOffset.Now:O}] {source}{Environment.NewLine}{error}{Environment.NewLine}{new string('-',72)}{Environment.NewLine}");}catch{}}
 protected override void OnStartup(StartupEventArgs e){base.OnStartup(e);if(e.Args.Contains("--icon-test")){ShellTest.Run(this);return;}if(e.Args.Contains("--shell-test")){ShellTest.Run(this);return;}if(e.Args.Length==2&&e.Args[0]=="--layer-hold"){ShutdownMode=ShutdownMode.OnExplicitShutdown;Settings.Boxes.Add(new BoxConfig{Entries=[e.Args[1]]});RefreshDesktop();File.WriteAllText(e.Args[1]+".ready","ready");return;}if(e.Args.Contains("--menu-glass-test")){MenuGlassTest.Run(this);return;}if(e.Args.Contains("--glass-test")){GlassTest.Run(this);return;}if(e.Args.Contains("--ui-test")){UiTest.Run(this);return;}mutex=new(true,"Local\\DesktopBoxLY-v1",out var first);if(!first){Shutdown();return;}ShutdownMode=ShutdownMode.OnExplicitShutdown;
 try{Settings=Store.Load();}catch(Exception ex){MessageBox.Show("设置无法读取，已保留原文件。程序停止以避免覆盖。\n"+ex.Message);Shutdown();return;}
 try{DesktopIcons.Recover();DesktopLayer.RestoreNative();}catch(Exception ex){MessageBox.Show("桌面图标恢复失败，恢复记录已保留："+ex.Message);Shutdown();return;}
 ready=true;StartRecoveryHelper();foreach(var c in Settings.Boxes) Open(c);RefreshDesktop();desktopTimer.Tick+=(_,_)=>{try{RefreshDesktop();}catch(Exception ex){desktop?.Dispose();desktop=null;desktopTimer.Stop();MessageBox.Show(ex.Message,"桌面图标层已恢复，请重新启动软件");}};desktopTimer.Start();
 manager=new Manager(this); manager.Show(); tray=new Forms.NotifyIcon{Icon=AppIcons.TrayIcon(),Text="桌面盒子",Visible=true};var menu=new Forms.ContextMenuStrip();menu.Items.Add("管理盒子",null,(_,_)=>Dispatcher.Invoke(()=>{manager.Show();manager.Activate();}));menu.Items.Add("显示 / 隐藏",null,(_,_)=>Dispatcher.Invoke(Toggle));menu.Items.Add("退出",null,(_,_)=>Dispatcher.Invoke(Shutdown));tray.ContextMenuStrip=menu;tray.DoubleClick+=(_,_)=>Dispatcher.Invoke(()=>{manager.Show();manager.Activate();});}
 void StartRecoveryHelper(){var exe=Environment.ProcessPath!;var watchArgs="--watch "+Environment.ProcessId; if(Path.GetFileNameWithoutExtension(exe).Equals("dotnet",StringComparison.OrdinalIgnoreCase)) watchArgs="\""+typeof(Program).Assembly.Location+"\" "+watchArgs;System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(exe,watchArgs){UseShellExecute=false,CreateNoWindow=true});}
 internal void Open(BoxConfig c){var w=new BoxWindow(this,c);Windows.Add(w);w.Show();}
 internal void SetFrost(double value){Settings.Frost=Math.Clamp(value,0,100);foreach(var box in Windows)box.ApplyTransparency();manager?.ApplyMaterial();Save();}
 internal void SetTransparency(double value){Settings.Transparency=Math.Clamp(value,0,95);foreach(var box in Windows)box.ApplyTransparency();manager?.ApplyMaterial();Save();}
 internal void SetIntervals(int backgroundMs,int fileMs){Settings.BackgroundIntervalMs=Math.Clamp(backgroundMs,50,5000);Settings.FileIntervalMs=Math.Clamp(fileMs,250,60000);foreach(var box in Windows)box.ApplyTiming();manager?.ApplyMaterial();Save();}
 internal DesktopLayer? Desktop=>desktop;
 internal void RefreshDesktop(){desktop??=new DesktopLayer(()=>Settings,()=>Windows);desktop.Refresh();}
 internal void RefreshManager()=>manager?.Refresh();
 internal void Save(){try{Store.Save(Settings);}catch(Exception ex){MessageBox.Show("保存失败："+ex.Message);}}
 internal void Toggle(){hidden=!hidden;if(hidden){foreach(var w in Windows){w.Topmost=false;w.Hide();}RefreshDesktop();return;}foreach(var w in Windows){w.Topmost=false;w.Show();}Windows.LastOrDefault()?.Activate();Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Background,new Action(RefreshDesktop));}
 internal void Delete(BoxWindow w){if(MessageBox.Show("删除盒子只移除配置，所有真实文件保留。继续？","删除盒子",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;Settings.Boxes.Remove(w.Config);Windows.Remove(w);w.DisposeAndClose();RefreshDesktop();Save();manager?.Refresh();}
 protected override void OnExit(ExitEventArgs e){desktopTimer.Stop();desktop?.Dispose();desktop=null;foreach(var w in Windows.ToArray())w.DisposeAndClose();if(ready)Save();tray?.Dispose();mutex?.Dispose();base.OnExit(e);}
}
