 internal Manager(Program app,bool registerHotkey=true){this.app=app;Icon=AppIcons.WindowIcon;Title="桌面盒子 · 管理";Width=480;Height=760;MinWidth=420;MinHeight=440;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;AllowsTransparency=true;Background=Brushes.Transparent;Foreground=Theme.Text;
 var panel=new StackPanel{Margin=new Thickness(22),Effect=new System.Windows.Media.Effects.DropShadowEffect{Color=Colors.Black,BlurRadius=2,ShadowDepth=1,Opacity=0.55}};var scroll=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};var header=new DockPanel{Background=Brushes.Transparent,Margin=new Thickness(0,0,0,4)};var close=Button("×",Hide);close.Width=30;close.Padding=new Thickness(0);close.FontSize=22;close.HorizontalContentAlignment=HorizontalAlignment.Center;close.Background=Brushes.Transparent;close.BorderThickness=new Thickness(0);DockPanel.SetDock(close,Dock.Right);header.Children.Add(close);MinimizeButton=Button("−",()=>WindowState=WindowState.Minimized);MinimizeButton.ToolTip="最小化";MinimizeButton.Width=30;MinimizeButton.Padding=new Thickness(0);MinimizeButton.FontSize=22;MinimizeButton.HorizontalContentAlignment=HorizontalAlignment.Center;MinimizeButton.Background=Brushes.Transparent;MinimizeButton.BorderThickness=new Thickness(0);DockPanel.SetDock(MinimizeButton,Dock.Right);header.Children.Add(MinimizeButton);header.Children.Add(new TextBlock{Text="桌面盒子",FontSize=26,VerticalAlignment=VerticalAlignment.Center});DragHeader.Child=header;DragHeader.PreviewMouseLeftButtonDown+=(_,e)=>{var node=e.OriginalSource as DependencyObject;while(node!=null){if(node is System.Windows.Controls.Primitives.ButtonBase)return;node=VisualTreeHelper.GetParent(node);}try{DragMove();e.Handled=true;}catch(InvalidOperationException){}};panel.Children.Add(DragHeader);panel.Children.Add(new TextBlock{Text="普通盒子保留文件位置；映射盒子拖入会移动文件。\n图标隐藏使用实验桌面层，退出恢复系统桌面。",Margin=new Thickness(0,12,0,12),TextWrapping=TextWrapping.Wrap});
