 BackgroundIntervalEditor.Text=Math.Clamp(app.Settings.BackgroundIntervalMs,50,5000).ToString();FileIntervalEditor.Text=Math.Clamp(app.Settings.FileIntervalMs,250,60000).ToString();AddTimingRow(panel,"磨砂采样",BackgroundIntervalEditor,[50,100,200,500,1000]);AddTimingRow(panel,"列表检查",FileIntervalEditor,[500,1000,2000,5000,10000]);panel.Children.Add(new TextBlock{Text="间隔单位：毫秒；列表同时响应文件夹变化。",Foreground=Theme.Muted,FontSize=11,Margin=new Thickness(0,2,0,12)});material=new GlassSurface(this,scroll,()=>app.Settings);
 panel.Children.Add(Button("＋ 普通盒子",()=>Create(false)));panel.Children.Add(Button("＋ 文件夹映射",()=>Create(true)));panel.Children.Add(Button("显示 / 隐藏所有盒子",app.Toggle));panel.Children.Add(Button("设置全局快捷键",ChangeHotkey));panel.Children.Add(new TextBlock{Text="默认 Ctrl + Alt + B；唤出盒子到前台，切换到其他应用后盒子可被覆盖。\n安全桌面、锁屏及部分独占全屏不可覆盖。",Margin=new Thickness(0,10,0,12)});panel.Children.Add(list);panel.Children.Add(Button("退出软件",app.Shutdown));
